sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) return;
    if (oldValue === newValue) return;

    // same helper as in onLoad (paste it here too)
    populateFromEmployee(newValue);
}

function populateFromEmployee(userSysId) {
    if (!userSysId) {
        g_form.setValue('department', '');
        g_form.setValue('employee_email', '');
        g_form.setValue('manager', '');
        g_form.setValue('manager_email', '');
        return;
    }

    g_form.getReference('employeename', function(u) {
        g_form.setValue('employee_email', u.email || '');
        if (u.department) g_form.setValue('department', u.department);

        if (u.manager) {
            g_form.setValue('manager', u.manager);
            g_form.getReference('manager', function(m) {
                g_form.setValue('manager_email', (m && m.email) ? m.email : '');
            });
        } else {
            g_form.setValue('manager', '');
            g_form.setValue('manager_email', '');
        }
    });
}
